import logging
from typing import Optional
from moler.device import DeviceFactory
from moler.exceptions import ConnectionObserverTimeout
from taf.rfrl.bts.devices.du.logs_collecting.btslog_collector import GnbBtslogCollector, EnbBtslogCollector
from taf.rfrl.utilities.parsers.pcap_checker import Checker
from taf.rfrl.utilities.logger import custom_logger as logger
from taf.rfrl.utilities.parsers.pcap_checker.utils import PcapProvider
from taf.rfrl.utilities.parsers.pcap_checker.messages import x2ap_messages, ngap_messages
from ute_ue import ute_ue


class UeAttachVerification(object):
    def __init__(self):
        self._observer = None
        self._ue = ute_ue()

        self.__nr_cell_id = None
        self.__beam_id = None

    @property
    def nr_cell_id(self):
        return self.__nr_cell_id

    @property
    def beam_id(self):
        return self.__beam_id

    def start_ue_rach_observer(self, bts_id=0, du_id=0, bts_type='GNB'):
        """
        Start observing RACH on syslog device.
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param bts_type: BTS Type used in test
        """
        btslog = GnbBtslogCollector() if bts_type == 'GNB' else EnbBtslogCollector()
        btslog.start_collecting_syslog()
        syslog = DeviceFactory.get_device(name=btslog.syslog_alias.format(bts_id, du_id))
        syslog.goto_state('SYSLOG', keep_state=False)
        self._observer = syslog.get_event(event_name="ue5g_rach",
                                          event_params={
                                              "till_occurs_times": 1}
                                          )
        self._observer.start()

    def verify_rach(self, timeout=60, stop_collecting_syslog=True, raise_exception=False, bts_type='GNB'):
        """

        :param timeout: Maximum time for waiting on RACH message.
        :param stop_collecting_syslog: Flag True/False if stop syslog collection at th end
        :param raise_exception: raise RachFailure exception when Rach fails.
        :param bts_type: BTS Type used in test
        """
        try:
            results = self._observer.await_done(timeout=timeout)[0]
            logging.debug("Detected events: {}".format(results))
            # self.__nr_cell_id = results[0]['named_groups']['NR_CELL_ID']
            # self.__beam_id = results[2]['named_groups']['BEAM']
            # MolerTest.info("UE attached to 5G. NR_CELL_ID={}, BEAM_ID={}".format(self.__nr_cell_id, self.__beam_id))
        except ConnectionObserverTimeout:
            if raise_exception:
                raise RachFailure("UE Attach to 5G failed. 5G Rach is not visible in syslog!")
            logging.warning("UE Attach to 5G failed. 5G Rach is not visible in syslog!.\n"
                            "It's in testing phase so if you think UE attached correctly please contact Tomasz Krol")
        finally:
            if stop_collecting_syslog:
                btslog = GnbBtslogCollector() if bts_type == 'GNB' else EnbBtslogCollector()
                btslog.stop_collecting_syslog()

    def verify_nsa_attach(self, ue_alias: str, pci_5g: int, pci_4g: Optional[int] = None,
                          awaited_messages: Optional[str] = None,
                          forbidden_messages: Optional[str] = None,
                          pcap_file: Optional[str] = None,
                          forbidden_messages_check: bool = True,
                          raise_on_error: bool = True) -> None:
        """
        Verify NSA attach. It checks optional 4G cell ID on UE and optional 5G flow in NSA pcap file.
        At least one verification source must be provided: `pci_4g` or `pcap_file`.

        :param ue_alias: UE alias
        :param pcap_file: pcap file name with attach flow
        :param pci_5g: physical cell ID of 5G cell
        :param pci_4g: physical cell ID of 4G cell; if None, 4G cell check is skipped
        :param awaited_messages: messages expected in pcap file
        :param forbidden_messages: messages that should not be present in pcap file
        :param forbidden_messages_check: determines if forbidden messages should be checked
        :param raise_on_error: determines if the function should raise an exception on verification error

        :return: None

        :raises CellID4GNotMatching: if 4G cell ID on UE is not matching with desired one
        """

        if pci_4g is None and pcap_file is None:
            raise ValueError("At least one verification input must be provided: pci_4g or pcap_file.")

        if pci_4g is not None:
            pci_4g = int(pci_4g)
            pci_4g_on_ue = int(self._ue.get_ue_info(ue_alias)['cell_id'])
            if pci_4g != pci_4g_on_ue:
                if raise_on_error:
                    raise CellID4GNotMatching(
                        f"4G Cell id obtained from UE: {pci_4g_on_ue} is not matching with desired one: {pci_4g}"
                    )
                else:
                    logger.warning(
                        f"4G Cell id obtained from UE: {pci_4g_on_ue} is not matching with desired one: {pci_4g}"
                    )

        if pcap_file:
            pci_5g = int(pci_5g)
            self._verify_nsa_attach_flow(
                pcap_file=pcap_file,
                pci_5g=pci_5g,
                awaited_messages=awaited_messages,
                forbidden_messages=forbidden_messages,
                forbidden_messages_check=forbidden_messages_check,
                raise_on_error=raise_on_error
            )

    def verify_sa_attach(self, ue_alias: str, pci_5g: int, awaited_messages: Optional[str] = None,
                         forbidden_messages: Optional[str] = None, pcap_file: Optional[str] = None,
                         forbidden_messages_check: bool = True, hex_len: int = 18,
                         raise_on_error: bool = True) -> None:
        """
        Verify SA attach if checks 5G cell ID in SA pcap file.
        If pcap file is not provided, The 5G cell ID will be only checked via get ue info,
        and SA pcap flow will not be check.

        :param ue_alias: UE alias
        :param pci_5g: physical cell ID of 5G cell
        :param awaited_messages: messages expected in pcap file
        :param forbidden_messages: messages that should not be present in pcap file
        :param pcap_file: pcap file name with attach flow
        :param forbidden_messages_check: determines if forbidden messages should be checked
        :param hex_len: length of hex string after '0x'
        :param raise_on_error: determines if the function should raise an exception on verification error

        :return: None

        :raises CellID5GNotMatching: if 5G cell ID in pcap file is not matching with desired one
        """

        pci_5g = int(pci_5g)
        pci_5g_on_ue = int(self._ue.get_ue_info(ue_alias)['cell_id'])
        if pci_5g != pci_5g_on_ue:
            if raise_on_error:
                raise CellID5GNotMatching(
                    f"5G Cell id obtained from UE: {pci_5g_on_ue} is not matching with desired one: {pci_5g}"
                )
            else:
                logger.warning(
                    f"5G Cell id obtained from UE: {pci_5g_on_ue} is not matching with desired one: {pci_5g}"
                )

        if pcap_file:
            self._verify_sa_attach_flow(
                pcap_file=pcap_file,
                pci_5g=pci_5g,
                awaited_messages=awaited_messages,
                forbidden_messages=forbidden_messages,
                forbidden_messages_check=forbidden_messages_check,
                hex_len=hex_len,
                raise_on_error=raise_on_error
            )

    def _verify_nsa_attach_flow(self, pcap_file: str, pci_5g: int, awaited_messages: Optional[str] = None,
                                forbidden_messages: Optional[str] = None,
                                forbidden_messages_check: bool = True,
                                raise_on_error: bool = True) -> None:
        """
        Verify NSA attach flow in pcap file

        :param pcap_file: pcap file name with attach flow
        :param pci_5g: physical cell ID of 5G cell
        :param awaited_messages: messages expected in pcap file
        :param forbidden_messages: messages that should not be present in pcap file
        :param forbidden_messages_check: determines if forbidden messages should be checked
        :param raise_on_error: determines if the function should raise an exception on verification error

        :return: None
        """

        if awaited_messages is None:
            awaited_messages = [
                x2ap_messages.SGNB_ADDITION_REQUEST,
                x2ap_messages.create_sgnb_addition_request_acknowledge(pci_5g),
                x2ap_messages.SGNB_RECONFIGURATION_COMPLETE,
                x2ap_messages.SNS_STATUS_TRANSFER
            ]

        if forbidden_messages is None:
            forbidden_messages = [
                x2ap_messages.SGNB_MODIFICATION_REQUEST_FAILURE_INFORMATION,
                x2ap_messages.SGNB_RELEASE_REQUEST
            ]

        forbidden_messages = forbidden_messages if forbidden_messages_check else []

        pcap_provider = PcapProvider()
        checker = Checker(pcap_provider=pcap_provider)
        try:
            checker.expect_flow(
                pcap_file=pcap_file,
                display_filter='x2ap',
                awaited_messages=awaited_messages,
                forbidden_messages=forbidden_messages
            )
        except Exception as e:
            if raise_on_error:
                raise e
            else:
                logger.warning(
                    f"Failed to verify NSA attach flow in pcap file: {e}"
                )

    def _verify_sa_attach_flow(self, pcap_file: str, pci_5g: int, awaited_messages: Optional[str] = None,
                               forbidden_messages: Optional[str] = None, forbidden_messages_check: bool = True,
                               hex_len: int = 18, raise_on_error: bool = True) -> None:
        """
        Verify SA attach flow in pcap file

        :param pcap_file: pcap file name with attach flow
        :param pci_5g: physical cell ID of 5G cell
        :param awaited_messages: messages expected in pcap file
        :param forbidden_messages: messages that should not be present in pcap file
        :param forbidden_messages_check: determines if forbidden messages should be checked
        :param hex_len: length of hex string after '0x'
        :param raise_on_error: determines if the function should raise an exception on verification error

        :return: None
        """

        pci_5g = f"{int(pci_5g):#0{hex_len}x}"

        if awaited_messages is None:
            awaited_messages = [
                ngap_messages.create_initial_ue_message_registration_request(pci_5g),
                ngap_messages.INITIAL_CONTEXT_SETUP_REQUEST_PDU_SESSION,
                ngap_messages.INITIAL_CONTEXT_SETUP_RESPONSE_PDU_SESSION
            ]

        if forbidden_messages is None:
            forbidden_messages = [ngap_messages.UE_CONTEXT_RELEASE_COMMAND]

        forbidden_messages = forbidden_messages if forbidden_messages_check else []

        pcap_provider = PcapProvider()
        checker = Checker(pcap_provider=pcap_provider)
        try:
            checker.expect_flow(
                pcap_file=pcap_file,
                display_filter='ngap',
                awaited_messages=awaited_messages,
                forbidden_messages=forbidden_messages
            )
        except Exception as e:
            if raise_on_error:
                raise e
            else:
                logger.warning(
                    f"Failed to verify SA attach flow in pcap file: {e}"
                )


class RachFailure(Exception):
    pass


class CellID4GNotMatching(Exception):
    pass


class CellID5GNotMatching(Exception):
    pass
